<script setup lang="ts">
import {computed} from 'vue'
import {dayBadges,secondsText,type EmployeeMonth,type EffectiveDay} from '../attendanceMonth'
import {modeLabel} from '../attendancePolicy'
const props=defineProps<{employees:EmployeeMonth[];english:boolean}>(),emit=defineEmits<{select:[employee:EmployeeMonth,day:EffectiveDay]}>()
const dates=computed(()=>props.employees[0]?.days.map(d=>d.workDate)||[])
function label(row:EmployeeMonth,day:EffectiveDay){return `${row.name} ${day.workDate}: ${dayBadges(day,props.english).join(', ')||(props.english?(day.state==='not_applicable'?'Hours not applicable':'Normal — effective source'):(day.state==='not_applicable'?'工时不适用':'正常，来源有效'))}`}
</script>
<template><div class="wf-table-wrap am-grid"><table><thead><tr><th scope="col">{{english?'Employee':'员工'}}</th><th v-for="date in dates" :key="date" scope="col">{{date.slice(8)}}</th><th scope="col">{{english?'Totals':'合计'}}</th></tr></thead><tbody><tr v-for="row in employees" :key="row.employeeId"><th scope="row">{{row.name}}<small>{{row.employeeNo}}</small><small v-for="mode in [...new Set(row.days.map(d=>d.mode))]" :key="mode">{{modeLabel(mode,english)}}</small></th><td v-for="day in row.days" :key="day.workDate" :data-state="day.state"><button :aria-label="label(row,day)" :title="label(row,day)" @click="emit('select',row,day)"><span v-for="badge in dayBadges(day,english)" :key="badge" class="wf-badge">{{badge}}</span></button></td><td class="am-totals"><div>{{english?'Work':'工时'}}: {{row.days.every(d=>d.mode==='contract'||d.mode==='free')?(english?'N/A':'不适用'):secondsText(row.totals.workSeconds,english)}}</div><div>{{english?'Confirmed overtime':'已确定计薪加班'}}: {{secondsText(row.totals.overtimeSeconds,english)}}</div><div>{{english?'Pending overtime':'待确定计薪加班'}}: {{secondsText(row.totals.pendingOvertimeSeconds,english)}}</div><div>{{english?'Approved extra work':'批准额外工作'}}: {{secondsText(row.totals.extraWorkSeconds,english)}}</div><div>{{english?'Paid leave':'带薪假'}}: {{secondsText(row.totals.paidLeaveSeconds,english)}}</div><div>{{english?'Unpaid leave':'无薪假'}}: {{secondsText(row.totals.unpaidLeaveSeconds,english)}}</div><div>{{english?'Absence':'缺勤'}}: {{secondsText(row.totals.absenceSeconds,english)}}</div><div>{{english?'Pending items':'待处理事项'}}: {{row.totals.pendingCount}}</div></td></tr></tbody></table></div></template>
<style scoped>.am-grid{max-height:70vh}.am-grid table{border-collapse:separate;border-spacing:0}.am-grid th:first-child{position:sticky;left:0;z-index:1;min-width:145px;background:#f5f7fa}.am-grid thead th{position:sticky;top:0;z-index:2}.am-grid thead th:first-child{z-index:3}.am-grid th small{display:block;white-space:normal;font-weight:400}.am-grid td{vertical-align:top;padding:3px}.am-grid td button{min-width:76px;min-height:56px;width:100%;border:0;background:transparent;display:flex;flex-direction:column;gap:4px}.am-grid .wf-badge{margin:0;white-space:normal}.am-grid [data-state=pending],.am-grid [data-state=stale]{background:#fff6e8}.am-grid [data-state=future],.am-grid [data-state=unarranged],.am-grid [data-state=outside_employment]{background:#f1f4f7}.am-totals{position:sticky;right:0;background:white;font-size:12px;min-width:200px;box-shadow:-2px 0 3px #0001}</style>
